mapper.select:
SELECT reason_id
FROM reports_log
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
ORDER BY report_id DESC
LIMIT 1

mapper.update:
UPDATE reports_log
SET status = #{status},
    resolved_at = NOW(),
    resolution_action_id = #{resolutionActionId}
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND status = 'pending'
